from rest_framework import viewsets, permissions
from .models import PatentDraftFiling
from .serializers import PatentDraftFilingSerializer

class IsAssignedInventorOrPatentCounsel(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        is_inventor = request.user in obj.inventors.all()
        is_counsel = request.user.groups.filter(name="PatentCounsel").exists()
        return is_inventor or is_counsel

class PatentDraftFilingViewSet(viewsets.ModelViewSet):
    serializer_class = PatentDraftFilingSerializer
    permission_classes = [permissions.IsAuthenticated, IsAssignedInventorOrPatentCounsel]

    def get_queryset(self):
        user = self.request.user
        if user.groups.filter(name="PatentCounsel").exists():
            return PatentDraftFiling.objects.all()
        return PatentDraftFiling.objects.filter(inventors=user)
